"""Report measured artifacts only; never performs inference or reevaluates a test set."""
import json
from pathlib import Path
from match_model import RUN,NAMES

def main():
    results=json.loads((RUN/'results.json').read_text());search=json.loads((RUN/'search_summary.json').read_text())
    summaries={k:json.loads((RUN/k/'summary.json').read_text()) for k in ('model','shuffled')}
    lines=['# Seven-control Match experiment — measured results','','One new deterministic 3,000-example JUCE dataset; 2400/300/300 split. Train-only statistics, waveform-derived log-mel input. Six continuous native-range normalized targets plus waveform classification. No plugin inference or audio-thread model loading.','','| Parameter | CNN MAE / RMSE | DSP + mean MAE / RMSE | Training mean MAE / RMSE | Shuffled MAE / RMSE |','|---|---|---|---|---|']
    for key in NAMES:
        values=[results[m]['parameters'][key] for m in ('model','dsp_plus_mean','training_mean','shuffled')]
        lines.append('| '+key+' ('+values[0]['unit']+') | '+' | '.join(f"{v['mae']} / {v['rmse']}" for v in values)+' |')
    lines+=['','| Method | Normalized MSE | Wave accuracy |','|---|---|---|']
    for m in ('model','dsp_plus_mean','training_mean','shuffled'):
        lines.append(f"| {m} | {results[m]['normalized_mse']} | {results[m]['waveform']['accuracy']} |")
    ratio=results['shuffled']['normalized_mse']/results['model']['normalized_mse']
    lines+=['',f'Shuffled/real normalized-MSE ratio: {ratio}. This sanity check is not a proof of no leakage. Input mutation tests and independent WAV/statistics recomputation are separate checks.','',f"Offline forward timing: {results['latency']}",'','## Equal actual render budget','', 'DSP and CNN-seeded search each render exactly 96 candidates/reference, with the same objective and shared known note/gate. Sixteen preselected new synth test examples and eight new independent SciPy fixtures; no source timbral labels seed search. Gain is preserved. Search scores are technical distances, not perceived similarity.','']
    for group in ('held_out_synth','independent_scipy'):lines.append(f"- {group}: {search[group]}")
    lines+=['',f"Predeclared numeric gate passed: {search['numeric_gate_passed']}.",search['deployment'],'','A CNN parameter-error improvement does not by itself justify deployment. No held-out set was repeatedly reevaluated for tuning; no hyperparameter search followed results. The independent fixtures have a different oscillator/filter but still controlled simple notes; they do not establish arbitrary real-recording performance.','',f'Training summaries: {summaries}','', 'Full precision results, per-example CSV/NPZ, validation histories, immutable data/config identities, source snapshots and all rendered search receipts are under `ml/runs/match_model/`. Dataset is `ml/data/match_model_3000/`. No old model/checkpoint/results were replaced. Internal shared-scale spectrogram/envelope diagnostics are generated by the default Match path; they are not displayed in the plugin.']
    path=RUN/'RESULTS.md';path.write_text('\n'.join(lines)+'\n');print(path)
if __name__=='__main__':main()
